using System.Net;
using System.Net.Http.Json;
using CondoManager.Application;
using CondoManager.Domain;
using CondoManager.Infrastructure;
using Microsoft.EntityFrameworkCore;
using Npgsql;
using Microsoft.Extensions.DependencyInjection;
namespace CondoManager.IntegrationTests;
[Collection("PostgreSQL")]
public class FinalStatementTests
{
 private static async Task<T> Send<T>(HttpClient c,string path,object body){using var r=await c.PostAsJsonAsync(path,body,SecurityTestHost.Json);Assert.True(r.IsSuccessStatusCode,$"{path}: {r.StatusCode}: {await r.Content.ReadAsStringAsync()}");return (await r.Content.ReadFromJsonAsync<T>(SecurityTestHost.Json))!;}
 private static async Task<HttpStatusCode> Status(HttpClient c,string path,object body){using var r=await c.PostAsJsonAsync(path,body,SecurityTestHost.Json);return r.StatusCode;}
 private static async Task<T> Get<T>(HttpClient c,string path)=>(await c.GetFromJsonAsync<T>(path,SecurityTestHost.Json))!;
 private static string Path(ResidentFinanceTests.Fixture f)=>$"/api/final-statements/condominiums/{f.Base.Condo}";
 private static FinalInput Input(ResidentFinanceTests.Fixture f,Guid? previous=null)=>new(f.Base.Period,"Synthetic final statement",Guid.NewGuid(),PreviousVersionId:previous);
 private static async Task<ExpenseDto> Expense(ResidentFinanceTests.Fixture f,decimal amount,bool allocate=true,Guid? account=null)
 {
  var a=$"/api/accounting/condominiums/{f.Base.Condo}";var supplier=await Send<SupplierDto>(f.C,"/api/accounting/suppliers",new SupplierInput("Synthetic supplier",null,null,null,null,null,null,null));var e=await Send<ExpenseDto>(f.C,a+"/expenses",new ExpenseInput(f.Base.Period,supplier.Id,account??f.Base.Account,"SYN-"+Guid.NewGuid().ToString("N")[..8],new(2026,8,1),null,"Synthetic actual expense",amount,0,amount,null));await Send<JournalDto>(f.C,a+$"/expenses/{e.Id}/register",new PostingInput(Guid.NewGuid()));
  if(allocate){var budgets=await Get<BudgetDto[]>(f.C,f.Base.Base);var rule=budgets.Single(b=>b.Id==f.Budget).Lines[0].RuleId;var input=new AllocationPreviewInput(f.Base.Period,new(2026,1,1),new(2026,12,31),[new(e.Id,amount,rule)]);var ap=$"/api/allocations/condominiums/{f.Base.Condo}";var preview=await Send<AllocationPreviewDto>(f.C,ap+"/preview",input);await Send<AllocationRunDto>(f.C,ap+"/confirm",new AllocationConfirmInput(Guid.NewGuid(),preview.PreviewHash,input));}return e;
 }
 private static async Task<FinalDto> Approve(ResidentFinanceTests.Fixture f,FinalInput? input=null)
 {var s=await Send<FinalDto>(f.C,Path(f),input??Input(f));await Send<FinalDto>(f.C,Path(f)+$"/{s.Id}/propose",new{});return await Send<FinalDto>(f.C,Path(f)+$"/{s.Id}/approve",new FinalApproval(s.Snapshot.Fingerprint));}
 private static async Task<SettlementDto> Post(ResidentFinanceTests.Fixture f,FinalDto s)
 {var p=await Send<SettlementPreview>(f.C,Path(f)+$"/{s.Id}/settlement-preview",new SettlementPreviewInput(new(2026,12,31)));var b=await Send<SettlementDto>(f.C,Path(f)+$"/{s.Id}/settlement-confirm",new SettlementConfirm(Guid.NewGuid(),p.Date,p.Fingerprint));return await Send<SettlementDto>(f.C,Path(f)+$"/settlements/{b.Id}/post",new{});}
 private static Task<OpeningDto> Zero(ResidentFinanceTests.Fixture f)=>Send<OpeningDto>(f.C,Path(f)+$"/periods/{f.Base.Period}/opening",new OpeningInput(Guid.NewGuid(),OpeningMode.VerifiedZero,"Synthetic verified zero"));
 [PostgresFact] public async Task NumericalABCostsExcludeReceiptsPaymentsAndPostOnlyDifferenceThenCloseWithDebt()
 {
  await using var f=await ResidentFinanceTests.Setup(1000);await ResidentFinanceTests.Issue(f);await Zero(f);var expense=await Expense(f,1100);var rates=(await Get<CreditDto[]>(f.C,f.Path+"/credits")).Where(r=>r.PropertyUnitId==f.Units[0]).ToArray();var receipt=await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",f.Receipt(400,f.People[0],f.People[1]));await Send<ResidentReceiptDto>(f.C,f.Path+$"/receipts/{receipt.Id}/allocate",f.Allocate((rates[0].Id,125),(rates[1].Id,125),(rates[2].Id,125),(rates[3].Id,25)));
  await Send<JournalDto>(f.C,$"/api/accounting/condominiums/{f.Base.Condo}/expenses/{expense.Id}/payments",new PaymentInput(Guid.NewGuid(),f.Base.Period,f.Financial,new(2026,8,2),100,"Synthetic supplier payment"));
  var s=await Approve(f);Assert.Equal(1100,s.Snapshot.ActualTotal);Assert.Equal(0,s.Snapshot.Difference);var a=s.Snapshot.Positions.Single(p=>p.PropertyUnitId==f.Units[0]);Assert.Equal(50,a.EconomicAdjustment);Assert.Equal(150,a.FinancialBalance);Assert.Equal(new decimal[]{50,30,20},f.Units.Select(u=>s.Snapshot.Positions.Single(p=>p.PropertyUnitId==u).PostingDelta));
  var batch=await Post(f,s);Assert.Equal(batch.JournalEntryId,(await Send<SettlementDto>(f.C,Path(f)+$"/settlements/{batch.Id}/post",new{})).JournalEntryId);var balance=await Get<FinanceBalances>(f.C,f.Path+"/balances");Assert.Equal(700,balance.Residual);var review=await Get<ClosureReview>(f.C,Path(f)+$"/periods/{f.Base.Period}/review");Assert.True(review.CanClose,string.Join(" ",review.Checks));Assert.Equal(700,review.LedgerBalance);Assert.Contains(review.Checks,c=>c.Code=="OutstandingReceivables" && !c.Blocking);
  var close=new CloseInput(Guid.NewGuid(),review.Fingerprint);var c=await Send<ClosureDto>(f.C,Path(f)+$"/periods/{f.Base.Period}/close",close);Assert.Equal(c.Id,(await Send<ClosureDto>(f.C,Path(f)+$"/periods/{f.Base.Period}/close",close)).Id);Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,$"/api/accounting/condominiums/{f.Base.Condo}/receipts",new ReceiptInput(Guid.NewGuid(),f.Base.Period,f.Financial,new(2026,8,2),1,"Closed",null)));Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,$"/api/allocations/condominiums/{f.Base.Condo}/readings",new ReadingInput(f.Units[0],f.Base.Period,"COLDWATER",null,"M3",new(2026,1,1),ReadingBoundary.Initial,0,false,null,null)));
 }
 [PostgresFact] public async Task NegativeAndZeroAdjustmentsAreNotDuplicateDebitsAndUnallocatedReceiptsStaySeparate()
 {
  await using var f=await ResidentFinanceTests.Setup(1000);await ResidentFinanceTests.Issue(f);await Zero(f);await Expense(f,900);await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",f.Receipt(250));var s=await Approve(f);Assert.Equal(-100,s.Snapshot.Positions.Sum(p=>p.EconomicAdjustment));var b=await Post(f,s);var balance=await Get<FinanceBalances>(f.C,f.Path+"/balances");Assert.Equal(900,balance.Residual);Assert.Equal(250,balance.Unattributed);
  var reverse=await Send<SettlementDto>(f.C,Path(f)+$"/settlements/{b.Id}/reverse",new ReversalInput(Guid.NewGuid(),f.Base.Period,new(2026,12,31),"Synthetic explicit correction"));Assert.NotNull(reverse.ReversedJournalId);Assert.Equal(1000,(await Get<FinanceBalances>(f.C,f.Path+"/balances")).Residual);var replacement=await Approve(f,Input(f,s.Id));Assert.Equal(2,replacement.Version);await Post(f,replacement);Assert.Equal(FinalStatementStatus.Superseded,(await Get<FinalDto[]>(f.C,Path(f))).Single(x=>x.Id==s.Id).Status);
 }
 [PostgresFact] public async Task ImportedPriorBalanceAndCarryAreIdempotentAndNeverRepostReceivable()
 {
  await using var f=await ResidentFinanceTests.Setup(1000);await ResidentFinanceTests.Issue(f);var openingInput=new OpeningInput(Guid.NewGuid(),OpeningMode.Import,"Synthetic prior debt",[new(f.Units[0],f.People[0],100)]);var chart=await Get<AccountDto[]>(f.C,$"/api/accounting/condominiums/{f.Base.Condo}/accounts");var legacyJournal=await Send<JournalDto>(f.C,$"/api/accounting/condominiums/{f.Base.Condo}/journals",new JournalInput(Guid.NewGuid(),f.Base.Period,new(2026,1,1),"Synthetic unclassified legacy balance",null,[new(chart.Single(a=>a.Code=="100").Id,10,0),new(chart.First(a=>a.Type==AccountType.Equity && a.Purpose==AccountPurpose.General).Id,0,10)]));Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,Path(f)+$"/periods/{f.Base.Period}/opening",openingInput));await Send<JournalDto>(f.C,$"/api/accounting/condominiums/{f.Base.Condo}/journals/{legacyJournal.Id}/reverse",new ReversalInput(Guid.NewGuid(),f.Base.Period,new(2026,1,1),"Synthetic explicit legacy correction"));var opening=await Send<OpeningDto>(f.C,Path(f)+$"/periods/{f.Base.Period}/opening",openingInput);Assert.Equal(opening.Id,(await Send<OpeningDto>(f.C,Path(f)+$"/periods/{f.Base.Period}/opening",openingInput)).Id);await Expense(f,1000);var s=await Approve(f);Assert.Equal(600,s.Snapshot.Positions.Single(p=>p.PropertyUnitId==f.Units[0]).FinancialBalance);var b=await Post(f,s);Assert.Null(b.JournalEntryId);var review=await Get<ClosureReview>(f.C,Path(f)+$"/periods/{f.Base.Period}/review");var closure=await Send<ClosureDto>(f.C,Path(f)+$"/periods/{f.Base.Period}/close",new CloseInput(Guid.NewGuid(),review.Fingerprint));
  var period=await Send<AccountingPeriodDto>(f.C,$"/api/condominiums/{f.Base.Condo}/accounting-periods",new AccountingPeriodInput("NEXT","Next synthetic",new(2027,1,1),new(2027,12,31)));await Send<AccountingPeriodDto>(f.C,$"/api/condominiums/{f.Base.Condo}/accounting-periods/{period.Id}/open",new{});var carryInput=new OpeningInput(Guid.NewGuid(),OpeningMode.CarryForward,"Synthetic carry",SourceClosureId:closure.Id);var carry=await Send<OpeningDto>(f.C,Path(f)+$"/periods/{period.Id}/opening",carryInput);Assert.Null(carry.JournalEntryId);Assert.Equal(1100,carry.Positions.Sum(p=>p.Balance));Assert.Equal(carry.Id,(await Send<OpeningDto>(f.C,Path(f)+$"/periods/{period.Id}/opening",carryInput)).Id);Assert.Equal(1100,(await Get<FinanceBalances>(f.C,f.Path+"/balances")).Residual);Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,Path(f)+$"/periods/{period.Id}/opening",carryInput with{RequestId=Guid.NewGuid()}));
 }
 [PostgresFact] public async Task MissingAllocationsUndeterminedOpeningAndStaleCostsBlockApprovalAndClosing()
 {
  await using var f=await ResidentFinanceTests.Setup(1000);await ResidentFinanceTests.Issue(f);await Expense(f,1000,false);var p=await Send<FinalPreview>(f.C,Path(f)+"/preview",Input(f));Assert.Contains(p.Anomalies,a=>a.Code=="ExpenseUnallocated" && a.Blocking);Assert.Contains(p.Anomalies,a=>a.Code=="OpeningUndetermined");var review=await Get<ClosureReview>(f.C,Path(f)+$"/periods/{f.Base.Period}/review");Assert.False(review.CanClose);Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,Path(f)+$"/periods/{f.Base.Period}/close",new CloseInput(Guid.NewGuid(),review.Fingerprint)));Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,$"/api/condominiums/{f.Base.Condo}/accounting-periods/{f.Base.Period}/close",new{}));
 }
 [PostgresFact] public async Task SourceChangeAfterApprovalRequiresNewVersionAndConfirmChecksFinancialChanges()
 {
  await using var f=await ResidentFinanceTests.Setup(1000);await ResidentFinanceTests.Issue(f);await Zero(f);await Expense(f,1000);var s=await Approve(f);var preview=await Send<SettlementPreview>(f.C,Path(f)+$"/{s.Id}/settlement-preview",new SettlementPreviewInput(new(2026,12,31)));var confirmed=await Send<SettlementDto>(f.C,Path(f)+$"/{s.Id}/settlement-confirm",new SettlementConfirm(Guid.NewGuid(),preview.Date,preview.Fingerprint));var credit=(await Get<CreditDto[]>(f.C,f.Path+"/credits")).First();var r=await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",f.Receipt(10));await Send<ResidentReceiptDto>(f.C,f.Path+$"/receipts/{r.Id}/allocate",f.Allocate((credit.Id,10)));Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,Path(f)+$"/settlements/{confirmed.Id}/post",new{}));await Expense(f,100);Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,Path(f)+$"/{s.Id}/settlement-preview",new SettlementPreviewInput(new(2026,12,31))));var next=await Approve(f,Input(f,s.Id));Assert.Equal(1100,next.Snapshot.ActualTotal);
 }
 [PostgresFact] public async Task ConcurrentApprovalsAndClosureCannotDuplicateAndRolesScopesCsrfRemainEnforced()
 {
  await using var f=await ResidentFinanceTests.Setup(1000);await ResidentFinanceTests.Issue(f);await Zero(f);await Expense(f,1000);var s=await Send<FinalDto>(f.C,Path(f),Input(f));await Send<FinalDto>(f.C,Path(f)+$"/{s.Id}/propose",new{});var replies=await Task.WhenAll(Send<FinalDto>(f.C,Path(f)+$"/{s.Id}/approve",new FinalApproval(s.Snapshot.Fingerprint)),Send<FinalDto>(f.C,Path(f)+$"/{s.Id}/approve",new FinalApproval(s.Snapshot.Fingerprint)));Assert.Equal(replies[0].Id,replies[1].Id);await Post(f,replies[0]);
  using var viewer=f.Base.Host.Browser();await SecurityTestHost.Login(viewer,await f.Base.Host.Account(f.Base.Tenant,StudioRole.Viewer),f.Base.Tenant);Assert.Equal(HttpStatusCode.Forbidden,await Status(viewer,Path(f),Input(f)));Assert.Equal(HttpStatusCode.Forbidden,await Status(viewer,Path(f)+$"/{s.Id}/approve",new FinalApproval(s.Snapshot.Fingerprint)));await using var other=await ResidentFinanceTests.Setup();Assert.Equal(HttpStatusCode.NotFound,await Status(other.C,Path(f)+$"/{s.Id}/propose",new{}));Assert.Equal(HttpStatusCode.NotFound,await Status(f.C,Path(other),Input(f)));
  using var missing=f.Base.Host.Browser();await SecurityTestHost.Login(missing,await f.Base.Host.Account(f.Base.Tenant),f.Base.Tenant);missing.DefaultRequestHeaders.Remove("X-CSRF-TOKEN");Assert.Equal(HttpStatusCode.BadRequest,await Status(missing,Path(f),Input(f)));
  var sameTenant=await Send<CondominiumDto>(f.C,"/api/condominiums",new CondominiumInput("OTHER-FINAL","Other synthetic scope",null,"Synthetic","00000","Test","XX","Test"));var wrongPath=$"/api/final-statements/condominiums/{sameTenant.Id}";Assert.Equal(HttpStatusCode.NotFound,await Status(f.C,wrongPath,Input(f)));Assert.Equal(HttpStatusCode.NotFound,await Status(f.C,wrongPath+$"/{s.Id}/propose",new{}));
  using var collaborator=f.Base.Host.Browser();await SecurityTestHost.Login(collaborator,await f.Base.Host.Account(f.Base.Tenant,StudioRole.Collaborator),f.Base.Tenant);Assert.Equal(HttpStatusCode.Forbidden,await Status(collaborator,Path(f)+$"/{s.Id}/approve",new FinalApproval(s.Snapshot.Fingerprint)));
  var review=await Get<ClosureReview>(f.C,Path(f)+$"/periods/{f.Base.Period}/review");var input=new CloseInput(Guid.NewGuid(),review.Fingerprint);var closed=await Task.WhenAll(Send<ClosureDto>(f.C,Path(f)+$"/periods/{f.Base.Period}/close",input),Send<ClosureDto>(f.C,Path(f)+$"/periods/{f.Base.Period}/close",input));Assert.Equal(closed[0].Id,closed[1].Id);
 }
 [PostgresFact] public async Task PersonCreditScenarioCAndOffsettingDeltasKeepSeparateDebtors()
 {
  await using var f=await ResidentFinanceTests.Setup(1000);await ResidentFinanceTests.Issue(f);await Zero(f);var expense=await Expense(f,1000,false);var path=$"/api/allocations/condominiums/{f.Base.Condo}";var rule=await Send<RuleDto>(f.C,path+"/rules",new RuleInput("Personal actual",null,AllocationCriterion.DirectCharge,[new(AllocationCriterion.DirectCharge,100,null,null,null,null)]));await Send<RuleDto>(f.C,path+$"/rules/{rule.Id}/activate",new{});var allocation=new AllocationPreviewInput(f.Base.Period,new(2026,1,1),new(2026,12,31),[new(expense.Id,1000,rule.Id,DirectCharges:f.Units.Select((u,i)=>new DirectChargeInput(u,f.People[i],new decimal[]{550,250,200}[i])).ToArray())]);var preview=await Send<AllocationPreviewDto>(f.C,path+"/preview",allocation);await Send<AllocationRunDto>(f.C,path+"/confirm",new AllocationConfirmInput(Guid.NewGuid(),preview.PreviewHash,allocation));
  var rates=(await Get<CreditDto[]>(f.C,f.Path+"/credits")).Where(r=>r.PropertyUnitId==f.Units[1]).ToArray();var receipt=await Send<ResidentReceiptDto>(f.C,f.Path+"/receipts",f.Receipt(300,f.People[1]));await Send<ResidentReceiptDto>(f.C,f.Path+$"/receipts/{receipt.Id}/allocate",f.Allocate(rates.Select(r=>(r.Id,r.Amount)).ToArray()));var s=await Approve(f);var b=s.Snapshot.Positions.Single(p=>p.PropertyUnitId==f.Units[1]);Assert.Equal(-50,b.EconomicAdjustment);Assert.Equal(-50,b.FinancialBalance);var batch=await Post(f,s);Assert.NotNull(batch.JournalEntryId);Assert.Equal(0,batch.Snapshot.Delta);var balances=await Get<FinanceBalances>(f.C,f.Path+"/balances");Assert.Equal(-50,balances.Positions.Single(p=>p.PropertyUnitId==f.Units[1]).Residual);Assert.Equal(550,balances.Positions.Single(p=>p.PropertyUnitId==f.Units[0]).Residual);
 }
 [PostgresFact] public async Task CategoriesOnlyInBudgetOrActualAreVisibleWithoutDivisionByZero()
 {
  await using var f=await ResidentFinanceTests.Setup(1000);await ResidentFinanceTests.Issue(f);await Zero(f);var account=await Send<AccountDto>(f.C,$"/api/accounting/condominiums/{f.Base.Condo}/accounts",new AccountInput("NEW-COST","Synthetic additional category",AccountType.Expense,null,null));await Expense(f,1100,account:account.Id);var preview=await Send<FinalPreview>(f.C,Path(f)+"/preview",Input(f));var added=preview.Categories.Single(c=>c.AccountId==account.Id);Assert.Equal(0,added.Budget);Assert.Null(added.Percentage);Assert.Equal(1100,added.Actual);var absent=preview.Categories.Single(c=>c.AccountId==f.Base.Account);Assert.Equal(1000,absent.Budget);Assert.Equal(0,absent.Actual);Assert.Equal(-100,absent.Percentage);
 }
 [PostgresFact] public async Task UndeterminedDebtorAndChangedM05SourcesAreBlockingWithoutUsingCurrentOwner()
 {
  await using var f=await ResidentFinanceTests.Setup(1000);await Zero(f);await Expense(f,1000);var ambiguous=await Send<FinalPreview>(f.C,Path(f)+"/preview",Input(f));Assert.Contains(ambiguous.Anomalies,a=>a.Code=="DebtorUndetermined" && a.Blocking);await ResidentFinanceTests.Issue(f);var s=await Approve(f);
  var associations=await Get<AssociationDto[]>(f.C,$"/api/condominiums/{f.Base.Condo}/associations");var old=associations.Single(a=>a.PropertyUnitId==f.Units[0]);Assert.Equal(HttpStatusCode.NoContent,await Status(f.C,$"/api/condominiums/{f.Base.Condo}/associations/{old.Id}/end",new EndAssociationInput(new(2026,6,30))));await Send<AssociationDto>(f.C,$"/api/condominiums/{f.Base.Condo}/units/{f.Units[0]}/associations",new AssociationInput(f.People[1],UnitPersonRole.Owner,new(2026,7,1),null,1));var current=await Send<FinalPreview>(f.C,Path(f)+"/preview",Input(f));Assert.Equal(f.People[0],current.Positions.Single(p=>p.PropertyUnitId==f.Units[0]).PersonId);Assert.Equal(s.Snapshot.Fingerprint,current.Fingerprint);
  using var changed=await f.C.PutAsJsonAsync($"/api/condominiums/{f.Base.Condo}/units/{f.Units[0]}",new PropertyUnitInput("RENAMED",null,null,null,null,PropertyUnitKind.Apartment,null,null),SecurityTestHost.Json);changed.EnsureSuccessStatusCode();var stale=await Send<FinalPreview>(f.C,Path(f)+"/preview",Input(f));Assert.Contains(stale.Anomalies,a=>a.Code=="AllocationSourcesChanged" && a.Blocking);
 }
 [PostgresFact] public async Task PostingZeroIsIdempotentAndClosedSnapshotRemainsImmutableAfterLaterPayments()
 {
  await using var f=await ResidentFinanceTests.Setup(1000);await ResidentFinanceTests.Issue(f);await Zero(f);var expense=await Expense(f,1000);var s=await Approve(f);var batch=await Post(f,s);Assert.Null(batch.JournalEntryId);var review=await Get<ClosureReview>(f.C,Path(f)+$"/periods/{f.Base.Period}/review");var c=await Send<ClosureDto>(f.C,Path(f)+$"/periods/{f.Base.Period}/close",new CloseInput(Guid.NewGuid(),review.Fingerprint));var journal= (await Get<JournalDto[]>(f.C,$"/api/accounting/condominiums/{f.Base.Condo}/journals")).Single(j=>j.Kind==JournalKind.Expense && j.ExpenseDocumentId==expense.Id);Assert.Equal(journal.Id,(await Send<JournalDto>(f.C,$"/api/accounting/condominiums/{f.Base.Condo}/expenses/{expense.Id}/register",new PostingInput(journal.RequestId))).Id);
  var originalSnapshot=(await Get<FinalDto[]>(f.C,Path(f))).Single(x=>x.Id==s.Id).Snapshot;Assert.Equal(s.Snapshot.Fingerprint,originalSnapshot.Fingerprint);Assert.Equal(HttpStatusCode.Conflict,await Status(f.C,Path(f)+$"/settlements/{batch.Id}/reverse",new ReversalInput(Guid.NewGuid(),f.Base.Period,new(2026,12,31),"Closed")));
  await using var scope=f.Base.Host.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"FinalStatements\" SET \"Description\"={"Tampered"} WHERE \"Id\"={s.Id}"));await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"AccountingPeriods\" SET \"Status\"={1} WHERE \"Id\"={f.Base.Period}"));
 }
 [PostgresFact] public async Task ConcurrentPostingDuringClosureIsSerializedAndStaleChecklistCannotClose()
 {
  await using var f=await ResidentFinanceTests.Setup(1000);await ResidentFinanceTests.Issue(f);await Zero(f);await Expense(f,1000);var s=await Approve(f);await Post(f,s);var review=await Get<ClosureReview>(f.C,Path(f)+$"/periods/{f.Base.Period}/review");var outcomes=await Task.WhenAll(Status(f.C,Path(f)+$"/periods/{f.Base.Period}/close",new CloseInput(Guid.NewGuid(),review.Fingerprint)),Status(f.C,$"/api/accounting/condominiums/{f.Base.Condo}/receipts",new ReceiptInput(Guid.NewGuid(),f.Base.Period,f.Financial,new(2026,12,31),10,"Synthetic concurrent receipt",null)));Assert.Single(outcomes.Where(s=>s==HttpStatusCode.OK));Assert.Single(outcomes.Where(s=>s==HttpStatusCode.Conflict));
 }}
